export * as NavigationMenu from './navigation-menu.tsx';
export type {
  LinkOwnProps as NavigationMenuLinkOwnProps,
  LinkProps as NavigationMenuLinkProps,
  SurfaceOwnProps as NavigationMenuSurfaceOwnProps,
  SurfaceProps as NavigationMenuSurfaceProps,
  TriggerOwnProps as NavigationMenuTriggerOwnProps,
  TriggerProps as NavigationMenuTriggerProps,
} from './navigation-menu.tsx';

@layer hj.components {
  /*
   * Customise: --hj-navigation-menu-height (trigger height) · --hj-navigation-menu-radius (popup)
   *
   * Declared layout transition: the popup's width/height follow Base UI's measured
   * --popup-width / --popup-height, and the positioner glides between triggers, so the
   * surface morphs instead of closing and reopening. Contained (overflow clipped by the
   * Viewport), clamped, and only while the menu is open.
   */
  .hj-navigation-menu-root {
    font-family: var(--hj-font-sans);
  }
  .hj-navigation-menu-list {
    display: flex;
    align-items: center;
    gap: 2px;
    margin: 0;
    padding: 0;
    list-style: none;
  }
  .hj-navigation-menu-item {
    position: relative;
  }

  .hj-navigation-menu-trigger,
  .hj-navigation-menu-link[data-variant='item'] {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: calc(6px * var(--hj-density));
    height: var(--hj-navigation-menu-height, calc(36px * var(--hj-density-size)));
    padding: 0 calc(12px * var(--hj-density));
    border: 0;
    border-radius: var(--hj-radius-pill);
    background: transparent;
    color: var(--hj-fg-dim);
    font: 600 14px / 1 var(--hj-font-sans);
    text-decoration: none;
    white-space: nowrap;
    cursor: pointer;
    user-select: none;
    -webkit-tap-highlight-color: transparent;
    transition:
      background-color var(--hj-dur-fast) var(--hj-ease-out),
      color var(--hj-dur-fast) var(--hj-ease-out),
      transform var(--hj-dur-snappy) var(--hj-ease-snappy);
  }
  /* 44px hit area */
  .hj-navigation-menu-trigger::before,
  .hj-navigation-menu-link[data-variant='item']::before {
    content: '';
    position: absolute;
    inset: -4px 0;
  }
  .hj-navigation-menu-trigger:hover,
  .hj-navigation-menu-link[data-variant='item']:hover {
    background: color-mix(in srgb, var(--hj-fg) 6%, transparent);
    color: var(--hj-fg);
  }
  .hj-navigation-menu-trigger[data-popup-open] {
    background: color-mix(in srgb, var(--hj-fg) 6%, transparent);
    color: var(--hj-fg);
  }
  .hj-navigation-menu-trigger:active,
  .hj-navigation-menu-link[data-variant='item']:active {
    transform: scale(var(--hj-press));
    transition-duration: var(--hj-dur-fast), var(--hj-dur-fast), 70ms;
  }
  .hj-navigation-menu-link[data-variant='item'][data-active] {
    color: var(--hj-accent);
  }
  .hj-navigation-menu-trigger[data-disabled] {
    opacity: 0.4;
    cursor: not-allowed;
  }

  .hj-navigation-menu-icon {
    display: inline-flex;
    font-size: 15px;
    line-height: 0;
    color: var(--hj-fg-mute);
    transition: transform var(--hj-dur-snappy) var(--hj-ease-snappy);
  }
  .hj-navigation-menu-icon[data-popup-open] {
    transform: rotate(180deg);
    color: var(--hj-fg-dim);
  }

  .hj-navigation-menu-positioner {
    z-index: var(--hj-z-popover);
    width: var(--positioner-width);
    height: var(--positioner-height);
    max-width: var(--available-width);
    transition-property: top, left, right, bottom;
    transition-duration: var(--hj-dur-gentle-settle);
    transition-timing-function: var(--hj-ease-gentle-settle);
  }
  /* bridge the gap so the pointer can travel from trigger to popup */
  .hj-navigation-menu-positioner::before {
    content: '';
    position: absolute;
    inset: -10px 0 auto;
    height: 10px;
  }
  .hj-navigation-menu-positioner[data-instant] {
    transition: none;
  }

  .hj-navigation-menu-popup {
    position: relative;
    width: var(--popup-width);
    height: var(--popup-height);
    border: 1px solid var(--hj-line);
    border-radius: var(--hj-navigation-menu-radius, var(--hj-radius-md));
    corner-shape: var(--hj-corner-shape, round);
    background: var(--hj-surface-2);
    box-shadow: var(--hj-shadow-lift);
    color: var(--hj-fg);
    outline: none;
    transform-origin: var(--transform-origin);
    transition:
      opacity var(--hj-dur-base) var(--hj-ease-out),
      transform var(--hj-dur-snappy-settle) var(--hj-ease-snappy-settle),
      width var(--hj-dur-gentle-settle) var(--hj-ease-gentle-settle),
      height var(--hj-dur-gentle-settle) var(--hj-ease-gentle-settle);
  }
  .hj-navigation-menu-popup[data-starting-style],
  .hj-navigation-menu-popup[data-ending-style] {
    opacity: 0;
    transform: scale(0.96);
  }
  .hj-navigation-menu-popup[data-ending-style] {
    transition-duration: var(--hj-dur-fast);
    transition-timing-function: var(--hj-ease-out);
  }

  .hj-navigation-menu-viewport {
    position: relative;
    width: 100%;
    height: 100%;
    overflow: hidden;
    border-radius: inherit;
    corner-shape: inherit;
  }

  .hj-navigation-menu-content {
    width: max-content;
    max-width: min(560px, calc(100vw - 32px));
    padding: var(--hj-space-2);
    transition:
      opacity var(--hj-dur-base) var(--hj-ease-out),
      transform var(--hj-dur-gentle-settle) var(--hj-ease-gentle-settle);
  }
  .hj-navigation-menu-content[data-starting-style],
  .hj-navigation-menu-content[data-ending-style] {
    opacity: 0;
  }
  /* Content slides a short way in the direction the pointer moved between triggers. */
  .hj-navigation-menu-content[data-starting-style][data-activation-direction='left'] {
    transform: translateX(calc(-24px * var(--hj-travel)));
  }
  .hj-navigation-menu-content[data-starting-style][data-activation-direction='right'] {
    transform: translateX(calc(24px * var(--hj-travel)));
  }
  .hj-navigation-menu-content[data-ending-style][data-activation-direction='left'] {
    transform: translateX(calc(24px * var(--hj-travel)));
  }
  .hj-navigation-menu-content[data-ending-style][data-activation-direction='right'] {
    transform: translateX(calc(-24px * var(--hj-travel)));
  }

  .hj-navigation-menu-link[data-variant='card'] {
    display: block;
    padding: calc(10px * var(--hj-density)) calc(12px * var(--hj-density));
    border-radius: var(--hj-radius-sm);
    corner-shape: var(--hj-corner-shape, round);
    color: var(--hj-fg);
    text-decoration: none;
    outline-offset: -2px;
    transition:
      background-color var(--hj-dur-fast) var(--hj-ease-out),
      opacity var(--hj-dur-fast) var(--hj-ease-out);
  }
  .hj-navigation-menu-link[data-variant='card']:hover {
    background: color-mix(in srgb, var(--hj-fg) 5%, transparent);
  }
  .hj-navigation-menu-link[data-variant='card']:active {
    opacity: var(--hj-press-opacity);
  }
  .hj-navigation-menu-link[data-variant='card'][data-active] .hj-navigation-menu-link-title {
    color: var(--hj-accent);
  }
  .hj-navigation-menu-link-title {
    display: block;
    font: 600 14.5px / 1.3 var(--hj-font-sans);
    letter-spacing: -0.01em;
  }
  .hj-navigation-menu-link-description {
    display: block;
    margin-top: calc(3px * var(--hj-density));
    font-size: 13px;
    line-height: 1.45;
    color: var(--hj-fg-mute);
  }

  .hj-navigation-menu-arrow {
    width: 12px;
    height: 12px;
    background: var(--hj-surface-2);
    border-top: 1px solid var(--hj-line);
    border-left: 1px solid var(--hj-line);
    transform: rotate(45deg);
    transition: left var(--hj-dur-gentle-settle) var(--hj-ease-gentle-settle);
  }
  .hj-navigation-menu-arrow[data-side='bottom'] {
    top: -7px;
  }

  .hj-navigation-menu-backdrop {
    position: fixed;
    inset: 0;
    z-index: var(--hj-z-overlay);
    background: var(--hj-scrim);
    opacity: 0.2;
    transition: opacity var(--hj-dur-base) var(--hj-ease-out);
  }
  .hj-navigation-menu-backdrop[data-starting-style],
  .hj-navigation-menu-backdrop[data-ending-style] {
    opacity: 0;
  }
}

'use client';
import { NavigationMenu as Base } from '@base-ui/react/navigation-menu';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { elementPart, part } from '../../system/part.tsx';
import type { ElementPartProps, HanjiPart } from '../../system/part.tsx';
import { cls, flag, withDefaults } from '../../system/slot.ts';
import { ThemeScope } from '../../system/theme.tsx';

export const Root: HanjiPart<typeof Base.Root> = part(
  Base.Root,
  'NavigationMenu.Root',
  'hj-navigation-menu-root',
);
export const List: HanjiPart<typeof Base.List> = part(
  Base.List,
  'NavigationMenu.List',
  'hj-navigation-menu-list',
);
export const Item: HanjiPart<typeof Base.Item> = part(
  Base.Item,
  'NavigationMenu.Item',
  'hj-navigation-menu-item',
);
export const Icon: HanjiPart<typeof Base.Icon> = part(
  Base.Icon,
  'NavigationMenu.Icon',
  'hj-navigation-menu-icon',
);
export const Content: HanjiPart<typeof Base.Content> = part(
  Base.Content,
  'NavigationMenu.Content',
  'hj-navigation-menu-content',
);
export const Popup: HanjiPart<typeof Base.Popup> = part(
  Base.Popup,
  'NavigationMenu.Popup',
  'hj-navigation-menu-popup',
);
export const Viewport: HanjiPart<typeof Base.Viewport> = part(
  Base.Viewport,
  'NavigationMenu.Viewport',
  'hj-navigation-menu-viewport',
);
export const Arrow: HanjiPart<typeof Base.Arrow> = part(
  Base.Arrow,
  'NavigationMenu.Arrow',
  'hj-navigation-menu-arrow',
);
export const Backdrop: HanjiPart<typeof Base.Backdrop> = part(
  Base.Backdrop,
  'NavigationMenu.Backdrop',
  'hj-navigation-menu-backdrop',
);
/** Title line inside a card Link. */
export const LinkTitle: (props: ElementPartProps<'span'>) => React.ReactElement = elementPart(
  'span',
  'NavigationMenu.LinkTitle',
  'hj-navigation-menu-link-title',
);
/** One-line description under a LinkTitle. */
export const LinkDescription: (props: ElementPartProps<'span'>) => React.ReactElement = elementPart(
  'span',
  'NavigationMenu.LinkDescription',
  'hj-navigation-menu-link-description',
);

/** Portals to `<body>` but keeps the nearest `<Theme>`. */
export function Portal({ children, ...props }: Base.Portal.Props): React.ReactElement {
  return (
    <Base.Portal {...props}>
      <ThemeScope>{children}</ThemeScope>
    </Base.Portal>
  );
}

/** Places the popup under the active trigger and glides between triggers. */
export function Positioner(props: Base.Positioner.Props): React.ReactElement {
  const config = useHanjiConfig();
  const {
    className,
    sideOffset = 8,
    collisionPadding = 12,
    ...rest
  } = withDefaults(config, 'NavigationMenu.Positioner', props);
  return (
    <Base.Positioner
      {...rest}
      sideOffset={sideOffset}
      collisionPadding={collisionPadding}
      className={cls(
        config,
        'NavigationMenu.Positioner',
        'hj-navigation-menu-positioner',
        className,
      )}
    />
  );
}

export interface TriggerOwnProps {
  /** Append the chevron that turns 180° while the menu is open. @default true */
  chevron?: boolean;
}
export interface TriggerProps extends TriggerOwnProps, Base.Trigger.Props {}

/** A top-level item that opens its Content. */
export function Trigger(props: TriggerProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    chevron = true,
    className,
    children,
    ...rest
  } = withDefaults(config, 'NavigationMenu.Trigger', props);
  return (
    <Base.Trigger
      {...rest}
      className={cls(config, 'NavigationMenu.Trigger', 'hj-navigation-menu-trigger', className)}
    >
      {children}
      {chevron ? <Icon>{config.icons.chevronDown}</Icon> : null}
    </Base.Trigger>
  );
}

export interface LinkOwnProps {
  /** item = a top-level link in the List · card = a block link inside Content (title + description). */
  variant?: 'item' | 'card';
}
export interface LinkProps extends LinkOwnProps, Base.Link.Props {}

/** A link. Use render for your router's Link; `active` marks the current page. */
export function Link(props: LinkProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    variant = 'card',
    className,
    ...rest
  } = withDefaults(config, 'NavigationMenu.Link', props);
  return (
    <Base.Link
      {...rest}
      data-variant={variant}
      className={cls(config, 'NavigationMenu.Link', 'hj-navigation-menu-link', className)}
    />
  );
}

export interface SurfaceOwnProps {
  /** Draw the small arrow pointing at the trigger. @default false */
  arrow?: boolean;
  /** Gap between trigger and popup. @default 8 */
  sideOffset?: number;
}
export interface SurfaceProps extends SurfaceOwnProps, Base.Popup.Props {}

/**
 * Shorthand for Portal + Positioner + Popup + Viewport: the floating surface that shows the
 * active item's Content and morphs its size between items. Place it once, after the List.
 */
export function Surface({ arrow = false, sideOffset, ...popup }: SurfaceProps): React.ReactElement {
  return (
    <Portal>
      <Positioner sideOffset={sideOffset}>
        <Popup {...popup} data-arrow={flag(arrow)}>
          {arrow ? <Arrow /> : null}
          <Viewport />
        </Popup>
      </Positioner>
    </Portal>
  );
}
